mapper.select:
SELECT COALESCE(MAX(visit_count), 0)
FROM moondap.md_visit_daily
WHERE visit_date = #{visitDate}

SELECT COALESCE(MAX(participation_count), 0)
FROM moondap.md_visit_daily
WHERE visit_date = #{visitDate}

SELECT COALESCE(SUM(visit_count), 0)
FROM moondap.md_visit_daily
WHERE visit_date BETWEEN #{fromDate} AND #{toDate}

SELECT user_agent      AS userAgent,
       counted,
       SUM(hit_count)  AS hitCount
FROM moondap.md_user_agent_daily
WHERE visit_date BETWEEN #{fromDate} AND #{toDate}
  AND counted = #{counted}
GROUP BY user_agent, counted
ORDER BY hitCount DESC, user_agent ASC
LIMIT #{limit}

SELECT ip_address    AS ipAddress,
       first_seen_at AS firstSeenAt
FROM moondap.md_visit_log
WHERE visit_date = #{visitDate}
ORDER BY first_seen_at IS NULL ASC, first_seen_at ASC, ip_address ASC
LIMIT #{limit} OFFSET #{offset}
